    [Theory]
    [InlineData(5, 5, 5, null, 10)]
    [InlineData(5, 5, 5, null, 80)]
    [InlineData(5, 5, 5, null, 190)]
    [InlineData(0, 5, 0, null, 100)]
    [InlineData(0, 0, 5, null, 50)]
